#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using ld = long double;

#define all(a) a.begin(), a.end()
#define rall(a) a.rbegin(), a.rend()
#define rep(i, n) for(int i = 0; i < (n); i += 1)
#define len(a) ((int)(a).size())

const ll inf = 1e18;
mt19937 rnd(234);

int n;
vector<vector<pair<int, int>>> g;
vector<int> deg;
int num_gay;
int res;

void dfs1(int v, int p) {
    for (auto [to, dir] : g[v]) {
        if (to == p) continue;
        if (dir) {
            deg[v] += 1;
            deg[to] += 1;
        }
        dfs1(to, v);
    }
}

void dfs2(int v, int p) {
    assert(num_gay % 2 == 0);
    res = min(res, num_gay / 2);
    for (auto [to, dir] : g[v]) {
        if (to == p) continue;
        num_gay -= deg[v] % 2;
        num_gay -= deg[to] % 2;
        if (dir) {
            deg[v] -= 1;
            deg[to] -= 1;
        }
        else {
            deg[v] += 1;
            deg[to] += 1;
        }
        num_gay += deg[v] % 2;
        num_gay += deg[to] % 2;
        dfs2(to, v);
        num_gay -= deg[v] % 2;
        num_gay -= deg[to] % 2;
        if (dir) {
            deg[v] += 1;
            deg[to] += 1;
        }
        else {
            deg[v] -= 1;
            deg[to] -= 1;
        }
        num_gay += deg[v] % 2;
        num_gay += deg[to] % 2;
    }
}

inline void solve() {
    cin >> n;
    g.assign(n, {});
    rep(i, n - 1) {
        int u, v;
        cin >> u >> v;
        --u;
        --v;
        g[u].push_back(make_pair(v, 1));
        g[v].push_back(make_pair(u, 0));
    }
    deg.assign(n, 0);
    num_gay = 0;
    dfs1(0, -1);
    rep(v, n) {
        num_gay += deg[v] % 2;
    }
    res = n;
    dfs2(0, -1);
    cout << res << "\n";
}

int32_t main() {
    if (1) {
        ios::sync_with_stdio(0);
        cin.tie(0);
        cout.tie(0);
    }
    int t;
    cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}
